import React from 'react';
import axios from 'axios';
import InventoryList from './InventoryList';

export default class WarehouseDetails extends React.Component {
    url = 'http://localhost:5000';

    constructor(props) {
        super(props);
        this.state = {
            list: []
        };
    }

    componentDidMount() {
        axios.get(`${this.url}/warehouses`)
            .then(response => {

                this.setState({ list: response.data });
            })
            .catch(error => console.error(error));
    }

    editHandler = () => {
        axios.put(`${this.url}/warehouses`, {
                })
            .then(response => {
                this.setState(response.data);
            })
            .catch(error => console.error(error));
    }
    deleteHandler = () => {
        axios.delete(`${this.url}/warehouses/:id`)
            .then(response => {
                this.setState(response.data);
            })
            .catch(error => console.error(error));
    }

    render() {
        return (
            <div>
                <div>
                    <div>WAREHOUSE ADDRESS:</div>
                    <div>{ this.state.address }</div>
                </div>
                <div>
                <div>CONTACT NAME</div>
                    <div>{ this.state.contact.name }</div>
                    <div>{ this.state.contact.position }</div>
                </div>
                <div>
                  <div>CONTACT information</div>
                    <div>{this.state.contact.phone}</div>
                    <div>{ this.state.contact.email }</div>
                </div>
                <InventoryList/>
            </div>
        );
    }
}
